import{z as s,x as l,o as e,c as t,q as o,j as E,D as r,d as p,s as A,S as n}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"AppArmor 对照","description":"","frontmatter":{"title":"AppArmor 对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/apparmor.md","filePath":"cs/apparmor.md","lastUpdated":1791413859000}'),B={name:"cs/apparmor.md"};function d(m,a,u,c,_,f){const i=l("Mermaid");return e(),t("div",null,[a[2]||(a[2]=o('<h1 id="apparmor-对照" tabindex="-1">AppArmor 对照 <a class="header-anchor" href="#apparmor-对照" aria-label="Permalink to &quot;AppArmor 对照&quot;">​</a></h1><div class="epigraph"><p>AppArmor 按程序路径挂配置文件：允许哪些文件、网络、能力，策略对人更像「这个二进制的名单」，而不是全机类型图。</p><footer>—— 据 AppArmor 文档；Ubuntu 默认启用实践；[LSM](/cs/lsm-selinux) 为钩子先修</footer></div><p><a href="/cs/lsm-selinux">SELinux</a> 的类型系统强大也难写。缺口是 <strong>对照</strong>：同一 LSM 钩，AppArmor 用路径与配置文件。不是谁取代谁的评测文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>profile：<code>/usr/bin/foo</code> 可 r 某目录、net 等。学习模式记拒绝再生成规则。缺口：路径 vs inode——rename、bind mount、<a href="/cs/overlayfs">overlay</a> 会让路径策略与真实对象偏离；SELinux 跟 inode 类型走。本课不把 aa-genprof 教程写进正文。</p><p><span class="marginnote">术语翻译：profile 就是一份跟着二进制走的「行为白名单」——这个程序可以读哪些路径、能不能开网络、用哪些特权能力，逐条列名，名单外一律拒绝。它属于 MAC（强制访问控制）：名单由管理员钉死，程序作者自己说了不算。</span></p><p><span class="marginnote">unconfined 默认放行。容器运行时常叠一层 profile。对象仍是 MAC。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>exec 匹配 profile → 后续钩查名单。对照 SELinux AVC。对照 <a href="/cs/linux-capabilities">capabilities</a>：profile 可 deny cap。对照 <a href="/cs/fuse">FUSE</a>：路径在用户 FS 上更飘。</p>',9)),(e(),E(n,null,{default:r(()=>[A(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIN%5B%22%E4%BA%8C%E8%BF%9B%E5%88%B6%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20PROF%5B%22profile%22%5D%0A%20%20OPEN%5B%22open%22%5D%20--%3E%20PATH%5B%22%E8%B7%AF%E5%BE%84%E5%8C%B9%E9%85%8D%22%5D%0A%20%20PATH%20--%3E%20PROF%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>AppArmor 降低策略写作成本，换路径语义的裂缝。发行版选谁，课序要求懂两种 MAC 的对象不同。不要写成发行版战争。与 audit：拒绝同样可记。</p><p>硬链接、命名空间下的路径可见性是经典坑。</p><p>实现上：路径策略在 bind mount 和 namespace 里看见的路径与策略作者想的可能不同。学习模式生成的规则往往过宽。硬链接能让「按路径禁止」漏掉。 读法上只引用<a href="/cs/lsm-selinux">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p><span class="marginnote">直觉类比：学习模式（complain）相当于给程序戴记录仪——它照常运行，每个会被拦的动作都记进日志，跑一段时间后把日志整理成规则草稿。程序跑过什么才有什么：没执行到的分支规则里就不会出现，这就是生成规则常常过宽的原因。</span></p><p><span class="marginnote">常见误区：初学者容易以为「拦住路径就拦住了文件」。实际上改个名、做个硬链接、或换一条 bind mount 路径，同一个 inode 看到的路径字符串就变了，规则却还钉在旧路径上——SELinux 跟着 inode 标签走，正是不吃这套把戏。</span></p>',6)),(e(),E(n,null,{default:r(()=>[A(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACT%5B%22%E8%BF%9B%E7%A8%8B%E6%83%B3%E8%AF%BB%E6%95%8F%E6%84%9F%E6%96%87%E4%BB%B6%22%5D%20--%3E%20HOW%7B%22%E7%AD%96%E7%95%A5%E5%AF%B9%E8%B1%A1%E6%98%AF%E4%BB%80%E4%B9%88%3F%22%7D%0A%20%20HOW%20--%3E%7C%22AppArmor%3A%20%E6%AF%94%E5%AF%B9%E8%B7%AF%E5%BE%84%22%7C%20PATH%5B%22%E8%B7%AF%E5%BE%84%E5%AD%97%E7%AC%A6%E4%B8%B2%E5%8C%B9%E9%85%8D%22%5D%0A%20%20HOW%20--%3E%7C%22SELinux%3A%20%E6%A0%B8%E5%AF%B9%E6%A0%87%E7%AD%BE%22%7C%20INODE%5B%22%E7%9C%8B%20inode%20%E4%B8%8A%E7%9A%84%E7%B1%BB%E5%9E%8B%22%5D%0A%20%20PATH%20--%3E%20OKP%5B%22%E5%90%8D%E5%AD%97%E5%AF%B9%E5%BE%97%E4%B8%8A%3A%20%E6%94%BE%E8%A1%8C%22%5D%0A%20%20PATH%20--%3E%20BYP%5B%22rename%20%E6%88%96%E7%A1%AC%E9%93%BE%E6%8E%A5%E6%8D%A2%E4%BA%86%E5%90%8D%3A%20%E7%BB%95%E8%BF%87%22%5D%0A%20%20INODE%20--%3E%20OKI%5B%22%E4%B8%8D%E7%AE%A1%E5%8F%AB%E4%BB%80%E4%B9%88%E5%90%8D%2C%20%E6%A0%87%E7%AD%BE%E4%B8%8D%E5%8F%98%3A%20%E4%BB%8D%E6%8B%A6%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[p(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>AppArmor 对照</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 TOMOYO 第三家。不保证嵌入式默认。下一课把拒绝与系统调用记下来：auditd。</p><p>版本字段会变，课序钉的是机制对象「AppArmor 对照」，不是某一主线内核的结构体名。 后课默认：MAC 可以是类型或路径。内核审计框架，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AppArmor：按程序路径的名单型 MAC。</li><li>与 SELinux 同钩不同策略对象。</li><li>audit 是下一课。</li><li>出处：AppArmor 文档；LSM；Linux security。</li></ul>',7))])}const T=s(B,[["render",d]]);export{D as __pageData,T as default};
